-- Synthetic password-free test rows: no real records or AI calls. Always rolled back.
begin;
create temp table fixture(actor uuid default gen_random_uuid(),outsider uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),job uuid default gen_random_uuid(),special uuid default gen_random_uuid());
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
insert into auth.users(id,email,role,aud) select id,id::text||'@search-test.invalid','authenticated','authenticated' from fixture,lateral unnest(array[actor,outsider]) id;
insert into public.companies(id,name) select company,'Search A' from fixture union all select other_company,'Search B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'owner' from fixture union all select other_company,outsider,'owner' from fixture;
insert into public.candidates(company_id,processing_status,review_status,dados_extraidos,created_at)
 select company,'concluido','completed',jsonb_build_object('nome_completo','Pessoa '||n,'skills',array['JavaScript'],'localizacao','São Paulo','anos_experiencia_total',3),now()+n*interval '1 second' from fixture,generate_series(1,1101) n;
insert into public.candidates(id,company_id,processing_status,review_status,dados_extraidos,created_at)
 select special,company,'concluido','completed','{"nome_completo":"Márcia Especial","email":"marcia@example.test","skills":["Recursos Humanos","Excel"],"localizacao":"Vitória","anos_experiencia_total":8}',now()-interval '1 day' from fixture;
insert into public.candidates(company_id,processing_status,review_status,dados_extraidos) select company,'erro','pending','{"nome_completo":"Leitura falha","skills":["Não possui experiência com Excel"]}'::jsonb from fixture
 union all select company,'processando','draft','{"nome_completo":"Excel","email":"java@example.test"}' from fixture
 union all select other_company,'concluido','completed','{"nome_completo":"Márcia Especial"}' from fixture;
insert into public.jobs(company_id,titulo,descricao) select company,'Vaga '||n,'Desenvolvimento JavaScript' from fixture,generate_series(1,1101) n;
insert into public.jobs(id,company_id,titulo,descricao,criteria,categoria,created_at) select job,company,'Analista de Recursos Humanos','Gestão de pessoas e Excel','[{"kind":"skill","text":"Excel","required":true,"weight":5,"min_years":null,"source":null}]','jovem_aprendiz',now()-interval '1 day' from fixture;
update public.jobs set approved_hash=private.job_hash(private.job_payload(titulo,descricao,categoria,criteria)) where id=(select job from fixture);
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('entire company count and bounded page',(select (r->>'total')::int=1104 and (r->>'filtered')::int=1104 and jsonb_array_length(r->'items')=25 from fixture,lateral public.browse_candidates(company) r));
select pg_temp.ok('search reaches oldest row beyond 1000 without case or accent sensitivity',(select r->>'filtered'='1' and r->'items'->0->>'id'=special::text from fixture,lateral public.browse_candidates(company,'{"q":"MARCIA especial"}') r));
select pg_temp.ok('multi-term intent and equivalents search',(select r->>'filtered'='1101' from fixture,lateral public.browse_candidates(company,'{"q":"Buscar candidatos com JS em SAO PAULO"}') r));
select pg_temp.ok('skills equivalents plus location and experience',(select r->>'filtered'='1' from fixture,lateral public.browse_candidates(company,'{"skill":"RH MS Excel","location":"vitoria","minExperience":"8"}') r));
select pg_temp.ok('contacts and names never become competencies',(select r->>'filtered'='0' from fixture,lateral public.browse_candidates(company,'{"skill":"java"}') r));
select pg_temp.ok('negated skill does not match positive filter',(select r->>'filtered'='1' from fixture,lateral public.browse_candidates(company,'{"skill":"Excel"}') r));
select pg_temp.ok('unknown experience is not zero proven',(select r->>'filtered'='1102' from fixture,lateral public.browse_candidates(company,'{"minExperience":"0"}') r));
select pg_temp.ok('unknown location does not match city',(select r->>'filtered'='1101' from fixture,lateral public.browse_candidates(company,'{"location":"São Paulo"}') r));
select pg_temp.ok('processing and review filters combine',(select r->>'filtered'='1' from fixture,lateral public.browse_candidates(company,'{"processing":"erro","review":"pending"}') r));
select pg_temp.ok('no matches retains company total',(select r->>'filtered'='0' and r->>'total'='1104' and r->'items'='[]' from fixture,lateral public.browse_candidates(company,'{"q":"inexistente"}') r));
select pg_temp.ok('out-of-range page clamps to last page',(select r->>'page'='44' and jsonb_array_length(r->'items')=4 from fixture,lateral public.browse_candidates(company,'{}',2147483647) r));
select pg_temp.ok('adjacent pages do not repeat rows',(select not exists(select 1 from jsonb_array_elements(public.browse_candidates(company,'{}',0)->'items') a join jsonb_array_elements(public.browse_candidates(company,'{}',1)->'items') b on a->>'id'=b->>'id') from fixture));
select pg_temp.ok('job counts not truncated',(select r->>'total'='1102' and jsonb_array_length(r->'items')=25 from fixture,lateral public.browse_jobs(company) r));
select pg_temp.ok('job category and equivalent term cover entire base',(select r->>'filtered'='1' from fixture,lateral public.browse_jobs(company,'{"q":"rh","category":"jovem_aprendiz"}') r));
select pg_temp.ok('empty job category retains count',(select r->>'filtered'='0' and r->>'total'='1102' from fixture,lateral public.browse_jobs(company,'{"category":"jovem_aprendiz","status":"encerrada"}') r));
select pg_temp.ok('other company cannot be searched',(select public.browse_candidates(other_company)->>'total'='0' and public.browse_jobs(other_company)->>'total'='0' from fixture));
select pg_temp.ok('C plus plus remains different from C',not private.search_vector('C++')@@private.search_query('C'));
select pg_temp.ok('equivalence does not match inside words',not private.search_vector('javajavascript excelente')@@private.search_query('js excel'));
select public.save_candidate_review(company,special,0,'{"localizacao":"Curitiba","skills":["Postgres"]}',false,false) from fixture;
select pg_temp.ok('human correction immediately searchable',(select r->>'filtered'='1' from fixture,lateral public.browse_candidates(company,'{"location":"Curitiba","skill":"PostgreSQL"}') r));
select pg_temp.ok('old corrected terms immediately disappear',(select r->>'filtered'='0' from fixture,lateral public.browse_candidates(company,'{"location":"Vitoria"}') r));
reset role;
update public.candidates set review_status='completed' where id=(select special from fixture);
set local role service_role;
select set_config('test.searchrun',public.begin_ranking(actor,company,job,gen_random_uuid())->>'id',true) from fixture;
do $$declare batch jsonb;begin for batch in select jsonb_agg(jsonb_build_object('candidate_id',candidate_id,'score',90,'details',jsonb_build_object('formula','evidence-v3','criterios',jsonb_build_array(jsonb_build_object('text','Excel','required',true,'estado','atendido'))))) from (select candidate_id,((row_number() over(order by candidate_id))-1)/200 as page from public.ranking_entries where run_id=current_setting('test.searchrun')::uuid and reason is null) e group by page loop perform public.stage_ranking((select actor from fixture),current_setting('test.searchrun')::uuid,batch);end loop;end$$;
select public.finish_ranking(actor,current_setting('test.searchrun')::uuid) from fixture;
set local role authenticated;
select pg_temp.ok('ranking fully counted with bounded pages',(select r->>'total'='1104' and r->>'filtered'='1102' and jsonb_array_length(r->'items')=25 from fixture,lateral public.browse_ranking(company,current_setting('test.searchrun')::uuid) r));
select pg_temp.ok('ranking searches entire snapshot and experience',(select r->>'filtered'='1' from fixture,lateral public.browse_ranking(company,current_setting('test.searchrun')::uuid,'{"q":"marcia","location":"curitiba","minExperience":"8"}') r));
select pg_temp.ok('ranking pending list separate',(select r->>'filtered'='2' from fixture,lateral public.browse_ranking(company,current_setting('test.searchrun')::uuid,'{"outcome":"pending"}') r));
select pg_temp.ok('ranking requirements use saved evidence',(select r->>'filtered'='1102' from fixture,lateral public.browse_ranking(company,current_setting('test.searchrun')::uuid,'{"criterion":"MS Excel","criterionState":"atendido","required":"met","minScore":"80"}') r));
select pg_temp.ok('ranking empty filter is distinct from no evaluation',(select r->>'total'='1104' and r->>'filtered'='0' from fixture,lateral public.browse_ranking(company,current_setting('test.searchrun')::uuid,'{"criterion":"Excel","criterionState":"nao_atendido"}') r));
select pg_temp.ok('foreign run lookup leaks no counts',(select public.browse_ranking(other_company,current_setting('test.searchrun')::uuid)->>'total'='0' from fixture));
reset role;
update public.candidates set excluido=true where id=(select special from fixture);
set local role authenticated;
select pg_temp.ok('archived candidate removed immediately',(select public.browse_candidates(company,'{"q":"marcia"}')->>'filtered'='0' and public.browse_candidates(company)->>'total'='1103' from fixture));
select pg_temp.ok('historical result retained and flagged stale',(select stale from public.ranking_runs where id=current_setting('test.searchrun')::uuid));
reset role;
delete from public.company_members where company_id=(select company from fixture) and user_id=(select actor from fixture);
set local role authenticated;
select pg_temp.ok('revoked access blocks search and counts',(select public.browse_candidates(company)->>'total'='0' and public.browse_jobs(company)->>'total'='0' and public.browse_ranking(company,current_setting('test.searchrun')::uuid)->>'total'='0' from fixture));
reset role;
select jsonb_build_object('passed',count(*),'checks',jsonb_agg(name)) from results;
rollback;
